/**
 * Deterministic plain-English renderer for pricing configuration (T-104, AD-024).
 *
 * The review summary a business approves is generated by THIS code from the
 * compiled config — never by the AI — so what they read is exactly what the
 * pricing engine will execute.
 */

import type {
  WorkStepConfig,
  AddonConfig,
  MultiplierConfig,
  SuggestedField,
  ExpectedSignalConfig,
} from '@estimator/shared'

export interface DescribablePricing {
  baseFee: number
  minimumCharge: number
  workSteps: WorkStepConfig[]
  addons: AddonConfig[]
  multipliers: MultiplierConfig[]
  suggestedFields: SuggestedField[]
  expectedSignals: ExpectedSignalConfig[]
}

export interface PricingSection {
  title: string
  lines: string[]
}

function money(amount: number, symbol: string): string {
  const rounded = Math.round(amount * 100) / 100
  return `${symbol}${rounded % 1 === 0 ? rounded.toFixed(0) : rounded.toFixed(2)}`
}

function operatorPhrase(operator: string | undefined, value: unknown): string {
  const v = String(value ?? '')
  switch (operator) {
    case 'gt':
      return `is more than ${v}`
    case 'gte':
      return `is at least ${v}`
    case 'lt':
      return `is less than ${v}`
    case 'lte':
      return `is at most ${v}`
    case 'contains':
      return `includes "${v}"`
    case 'exists':
      return 'is provided'
    case 'not_exists':
      return 'is not provided'
    case 'equals':
    default:
      return `is "${v}"`
  }
}

function fieldLabel(fieldId: string, fields: SuggestedField[]): string {
  const field = fields.find((f) => f.fieldId === fieldId)
  return field ? `"${field.label}"` : `"${fieldId}"`
}

function signalLabel(signalKey: string, signals: ExpectedSignalConfig[]): string {
  const signal = signals.find((s) => s.signalKey === signalKey)
  return signal?.description || signalKey
}

function describeWorkStep(
  step: WorkStepConfig,
  pricing: DescribablePricing,
  symbol: string
): string {
  let line: string

  if (step.costType === 'per_unit' || step.costType === 'per_hour') {
    const unit = step.unitLabel || (step.costType === 'per_hour' ? 'hour' : 'unit')
    line = `${step.name}: ${money(step.defaultCost, symbol)} per ${unit}`

    const qs = step.quantitySource
    if (qs?.type === 'form_field' && qs.fieldId) {
      line += ` — quantity from the customer's answer to ${fieldLabel(qs.fieldId, pricing.suggestedFields)}`
    } else if (qs?.type === 'ai_signal' && qs.signalKey) {
      line += ` — quantity estimated by AI from photos (${signalLabel(qs.signalKey, pricing.expectedSignals)})`
    } else if (qs?.type === 'constant') {
      line += ` — fixed quantity of ${qs.value ?? 1}`
    } else {
      line += ` — no quantity source configured (defaults to 1)`
    }
  } else {
    line = `${step.name}: ${money(step.defaultCost, symbol)} (fixed)`
  }

  if (step.optional && step.triggerSignal) {
    const signalName = signalLabel(step.triggerSignal, pricing.expectedSignals)
    if (step.triggerCondition) {
      line += `. Only charged when ${signalName} ${operatorPhrase(step.triggerCondition.operator, step.triggerCondition.value)}`
    } else {
      line += `. Only charged when ${signalName} applies`
    }
  }

  return line
}

function describeAddon(addon: AddonConfig, symbol: string): string {
  let line = `${addon.label}: +${money(addon.price, symbol)}`
  const triggers: string[] = []
  if (addon.triggerKeywords?.length) {
    triggers.push(`the customer mentions ${addon.triggerKeywords.map((k) => `"${k}"`).join(', ')}`)
  }
  if (addon.triggerConditions?.length) {
    triggers.push(`photos show ${addon.triggerConditions.map((c) => c.replace(/_/g, ' ')).join(', ')}`)
  }
  if (triggers.length > 0) {
    line += ` — suggested automatically when ${triggers.join(' or ')}`
  }
  return line
}

function describeMultiplier(m: MultiplierConfig, pricing: DescribablePricing): string {
  const conditionValue = m.when.equals ?? m.when.value
  const pct = Math.round((m.multiplier - 1) * 100)
  const effect =
    m.multiplier >= 1
      ? `increase the price by ${pct}%`
      : `decrease the price by ${Math.abs(pct)}%`
  // T-125: subtotal-conditioned multipliers (order-value rules) have no field
  if (m.when.subject === 'subtotal' || !m.when.fieldId) {
    return `When the job total ${operatorPhrase(m.when.operator, conditionValue)}: ${effect} (×${m.multiplier})`
  }
  const label = fieldLabel(m.when.fieldId, pricing.suggestedFields)
  return `When ${label} ${operatorPhrase(m.when.operator, conditionValue)}: ${effect} (×${m.multiplier})`
}

/**
 * Render a pricing configuration as grouped plain-English sections.
 */
export function describePricingRules(
  pricing: DescribablePricing,
  currencySymbol = '$'
): PricingSection[] {
  const sections: PricingSection[] = []

  const baseLines: string[] = []
  if (pricing.baseFee > 0) {
    baseLines.push(`Base fee: ${money(pricing.baseFee, currencySymbol)} — added to every quote`)
  }
  if (pricing.minimumCharge > 0) {
    baseLines.push(
      `Minimum charge: ${money(pricing.minimumCharge, currencySymbol)} — applied if the total comes in lower`
    )
  }
  if (baseLines.length > 0) {
    sections.push({ title: 'Base pricing', lines: baseLines })
  }

  if (pricing.workSteps.length > 0) {
    sections.push({
      title: 'Price breakdown',
      lines: pricing.workSteps.map((step) => describeWorkStep(step, pricing, currencySymbol)),
    })
  }

  if (pricing.addons.length > 0) {
    sections.push({
      title: 'Optional extras',
      lines: pricing.addons.map((addon) => describeAddon(addon, currencySymbol)),
    })
  }

  if (pricing.multipliers.length > 0) {
    sections.push({
      title: 'Price adjustments',
      lines: pricing.multipliers.map((m) => describeMultiplier(m, pricing)),
    })
  }

  return sections
}

/**
 * Flatten sections to a single editable text block — used to pre-fill the
 * composer when editing an existing service (round-trip: rules → English → rules).
 */
export function describePricingAsText(
  pricing: DescribablePricing,
  currencySymbol = '$'
): string {
  return describePricingRules(pricing, currencySymbol)
    .map((section) => `${section.title}:\n${section.lines.map((l) => `- ${l}`).join('\n')}`)
    .join('\n\n')
}
